14","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 73 · CC BY 4.0","verified":true},{"id":"srd-5.1-es-tools-context","kind":"srd","title":"SRD 5.1 · herramientas, instrumentos y juegos · español oficial","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · páginas PDF 72–73 · CC BY 4.0","verified":true}],"category":"tool","subtypes":[],"magical":false,"rarity":"none","consumable":false,"properties":[],"weight":{"value":2,"unit":"lb"},"economy":{"basePrice":{"quantity":50,"unit":"gp"},"campaignPrice":null,"explanation":"Precio cotejado con la tabla oficial de 2014. Los precios de las copias de personajes y comerciantes se conservan."},"description":[{"id":"official-table-row","section":"description","provenance":"reviewed-translation","sourceIds":["srd-5.1-en-equipment"],"type":"table","columns":["Objeto","Precio","Peso"],"rows":[["Kit de envenenamiento","50 po","2 lb."]]},{"id":"official-prose","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Útiles de envenenador. Los útiles de envenenador incluyen viales, productos químicos y todo el equipo necesario para crear venenos. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para fabricar o usar venenos."},{"id":"tools-context-general","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-tools-context"],"type":"paragraph","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza."}],"requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"Equipo mundano; no requiere sintonización."},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"mundane-rule","name":"Uso del equipo","activation":"other","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"Equipo mundano; no requiere sintonización."},"target":"Según las reglas del objeto.","range":"","duration":"Según la regla.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"tool-check","kind":"tool-check","toolKey":"poisoners-kit","condition":""}],"execution":{"mode":"automatic","handler":"equipment-tool-check","explanation":"Prueba de herramienta con característica elegida, competencia, pericia y Talento Seguro cuando corresponden.","pendingAutomation":[]},"textBlockIds":["official-prose"]}],"recoverySourceIds":["ecd3e59abfaa2bc4f36e0a88326a17232d08fa0d107fdc13f32396e149d827dd","f09bb120c5ea4ec8bfc1a12b0314c1049191b464b9922475b67de98c79ea9ace","ffa5fc1b1bd0ddc52de3594aa9bd3e4ea582511f621c9a205f1f8dab73c02f19","0eba8a11a5d939410b928a033f0cc9d139fcac5ebd2f2bfa4e0fce9870bfd780"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Conservar los originales y cerrar la recuperación de información antes de eliminar versiones.","El uso particular continúa siendo asistido y está explicado en el objeto."]}}$native_14b084d62b7e2322$::jsonb,true),'{features}',$native_a3df671d48b1157e$[{"id":"mundane-rule","kind":"other","name":"Uso del equipo","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Útiles de envenenador. Los útiles de envenenador incluyen viales, productos químicos y todo el equipo necesario para crear venenos. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para fabricar o usar venenos.\n\nResolver las reglas descritas y sus condiciones en la mesa.\n\nDuración: Según la regla..","showInActions":false}]$native_a3df671d48b1157e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:73d1f95b3a80f2914d62adb4';
